function buildTopic(data: { n: string; s: string; d: string; t: string[] }[]): Nivel[] {
  return data.map((x, i) => ({
    id: i,
    nombre: x.n,
    subtitulo: x.s,
    color: PAL[i % PAL.length],
    colorHex: PALHEX[i % PALHEX.length],
    icono: i === 0 ? '🗺️' : i === data.length - 1 ? '🔱' : String(i),
    descripcion: x.d,
    tags: x.t,
  }));
}

